import { useMemo, useState } from 'react';
import {
  Badge,
  Button,
  Card,
  Chip,
  EmptyState,
  Pagination,
  Stack,
  Text,
} from '@jinx-ui/react';

type ProjectStatus = 'active' | 'paused' | 'archived' | 'overdue';

interface Project {
  id: string;
  name: string;
  quotaUsedPercent: number;
  status: ProjectStatus;
}

interface SpendPanelProps {
  projects?: Project[];
  pageSize?: number;
}

const STATUS_META: Record<ProjectStatus, { label: string; tone: string }> = {
  active: { label: 'Активен', tone: 'success' },
  paused: { label: 'На паузе', tone: 'warning' },
  archived: { label: 'В архиве', tone: 'neutral' },
  overdue: { label: 'Превышен', tone: 'danger' },
};

const STATUS_ORDER: ProjectStatus[] = ['active', 'paused', 'overdue', 'archived'];

const DEFAULT_PROJECTS: Project[] = [
  { id: 'p-01', name: 'Витрина каталога', quotaUsedPercent: 32, status: 'active' },
  { id: 'p-02', name: 'Биллинг и подписки', quotaUsedPercent: 87, status: 'overdue' },
  { id: 'p-03', name: 'Мобильный клиент', quotaUsedPercent: 54, status: 'active' },
  { id: 'p-04', name: 'Аналитика событий', quotaUsedPercent: 12, status: 'paused' },
  { id: 'p-05', name: 'Поисковый индекс', quotaUsedPercent: 76, status: 'active' },
  { id: 'p-06', name: 'Импорт партнёров', quotaUsedPercent: 100, status: 'overdue' },
  { id: 'p-07', name: 'Легаси-платежи', quotaUsedPercent: 4, status: 'archived' },
  { id: 'p-08', name: 'Уведомления', quotaUsedPercent: 61, status: 'paused' },
  { id: 'p-09', name: 'Медиа-хранилище', quotaUsedPercent: 45, status: 'active' },
  { id: 'p-10', name: 'Отчёты для финансов', quotaUsedPercent: 23, status: 'archived' },
  { id: 'p-11', name: 'A/B-платформа', quotaUsedPercent: 68, status: 'active' },
  { id: 'p-12', name: 'Шлюз интеграций', quotaUsedPercent: 91, status: 'overdue' },
];

const RING_SIZE = 44;
const RING_RADIUS = 17;
const RING_LENGTH = 2 * Math.PI * RING_RADIUS;

function QuotaRing({ value, status }: { value: number; status: ProjectStatus }) {
  const safeValue = Math.min(100, Math.max(0, value));
  const strokeColor =
    status === 'overdue' ? 'var(--jx-color-danger)' : 'var(--jx-color-primary)';

  return (
    <div
      className="jx-flex jx-items-center jx-justify-center"
      role="img"
      aria-label={`Квота использована на ${safeValue}%`}
      style={{ width: RING_SIZE, height: RING_SIZE, position: 'relative' }}
    >
      <svg width={RING_SIZE} height={RING_SIZE} style={{ transform: 'rotate(-90deg)' }}>
        <circle
          cx={RING_SIZE / 2}
          cy={RING_SIZE / 2}
          r={RING_RADIUS}
          fill="none"
          stroke="var(--jx-color-border-subtle)"
          strokeWidth={4}
        />
        <circle
          cx={RING_SIZE / 2}
          cy={RING_SIZE / 2}
          r={RING_RADIUS}
          fill="none"
          stroke={strokeColor}
          strokeWidth={4}
          strokeLinecap="round"
          strokeDasharray={RING_LENGTH}
          strokeDashoffset={RING_LENGTH * (1 - safeValue / 100)}
        />
      </svg>
      <Text
        size="xs"
        weight="medium"
        style={{
          position: 'absolute',
          insetInlineStart: 0,
          insetInlineEnd: 0,
          textAlign: 'center',
        }}
      >
        {safeValue}%
      </Text>
    </div>
  );
}

export default function ProjectSpendPanel({
  projects = DEFAULT_PROJECTS,
  pageSize = 5,
}: SpendPanelProps) {
  const [activeStatuses, setActiveStatuses] = useState<ProjectStatus[]>([]);
  const [page, setPage] = useState(1);

  const filtered = useMemo(
    () =>
      activeStatuses.length === 0
        ? projects
        : projects.filter((project) => activeStatuses.includes(project.status)),
    [projects, activeStatuses],
  );

  const totalPages = Math.max(1, Math.ceil(filtered.length / pageSize));
  const currentPage = Math.min(page, totalPages);
  const visible = filtered.slice((currentPage - 1) * pageSize, currentPage * pageSize);

  const toggleStatus = (status: ProjectStatus) => {
    setActiveStatuses((prev) =>
      prev.includes(status) ? prev.filter((item) => item !== status) : [...prev, status],
    );
    setPage(1);
  };

  const resetFilters = () => {
    setActiveStatuses([]);
    setPage(1);
  };

  return (
    <Card className="jx-p-4">
      <Stack direction="vertical" gap="lg">
        <Stack direction="vertical" gap="sm">
          <Text as="h2" size="lg" weight="semibold">
            Расход по проектам
          </Text>
          <Stack direction="horizontal" gap="sm" wrap>
            {STATUS_ORDER.map((status) => {
              const selected = activeStatuses.includes(status);
              return (
                <Chip
                  key={status}
                  selected={selected}
                  tone={STATUS_META[status].tone}
                  onClick={() => toggleStatus(status)}
                  onDismiss={selected ? () => toggleStatus(status) : undefined}
                  aria-pressed={selected}
                >
                  {STATUS_META[status].label}
                </Chip>
              );
            })}
          </Stack>
        </Stack>

        {visible.length === 0 ? (
          <EmptyState
            title="Ничего не найдено"
            description="Под выбранные статусы не подходит ни один проект."
          >
            <Button variant="secondary" onClick={resetFilters}>
              Сбросить фильтры
            </Button>
          </EmptyState>
        ) : (
          <Stack direction="vertical" gap="sm">
            {visible.map((project) => (
              <Card key={project.id} variant="outlined" className="jx-p-3">
                <Stack direction="horizontal" gap="md" align="center" justify="between">
                  <Stack direction="horizontal" gap="md" align="center">
                    <QuotaRing value={project.quotaUsedPercent} status={project.status} />
                    <Text weight="medium">{project.name}</Text>
                  </Stack>
                  <Badge tone={STATUS_META[project.status].tone}>
                    {STATUS_META[project.status].label}
                  </Badge>
                </Stack>
              </Card>
            ))}
          </Stack>
        )}

        {visible.length > 0 && totalPages > 1 && (
          <Stack direction="horizontal" justify="center">
            <Pagination page={currentPage} count={totalPages} onChange={setPage} />
          </Stack>
        )}
      </Stack>
    </Card>
  );
}

